// ── Read Reviews Source ─────────────────────────────────────────
// Production: replace with HTTP Request to Amazon SP-API / Shopify API,
// database query, or read from CSV file via Read/Write File node.

const reviews = [
  {
    review_id: "r001",
    platform: "Amazon",
    product_name: "Wireless Security Camera",
    rating: 2,
    review_text: "Battery drains too fast and the night vision is blurry.",
    country: "US",
    created_at: "2026-06-01"
  },
  {
    review_id: "r002",
    platform: "Shopify",
    product_name: "Solar Battery Camera",
    rating: 1,
    review_text: "The solar panel doesn't charge the battery at all. Dead after 3 sunny days.",
    country: "DE",
    created_at: "2026-06-01"
  },
  {
    review_id: "r003",
    platform: "Amazon",
    product_name: "Smart Doorbell Camera",
    rating: 5,
    review_text: "Super easy to install, excellent video quality even at night. Best doorbell camera!",
    country: "US",
    created_at: "2026-06-02"
  },
  {
    review_id: "r004",
    platform: "Amazon",
    product_name: "Indoor Pet Camera",
    rating: 3,
    review_text: "The two-way audio has a 2-second delay which confuses my dog. Otherwise decent.",
    country: "JP",
    created_at: "2026-06-02"
  },
  {
    review_id: "r005",
    platform: "Shopify",
    product_name: "WiFi Camera System",
    rating: 2,
    review_text: "NVR keeps disconnecting from WiFi every few hours. Tried factory reset, no luck.",
    country: "UK",
    created_at: "2026-06-02"
  },
  {
    review_id: "r006",
    platform: "Amazon",
    product_name: "Baby Monitor Camera",
    rating: 1,
    review_text: "Camera stopped working after 3 weeks. Power adapter gets extremely hot.",
    country: "US",
    created_at: "2026-06-03"
  }
];

// For batch mode: wrap all reviews in a single item
return [{ json: { reviews: reviews } }];

// ── Validate Batch Analysis Response ────────────────────────────
const batch = $input.first().json;
const issues = [];

// Check 1: results array exists
if (!Array.isArray(batch.results)) {
  issues.push("results is not an array");
}

// Check 2: total matches
if (batch.total !== (batch.results || []).length) {
  issues.push(`total (${batch.total}) != results.length (${(batch.results || []).length})`);
}

// Check 3: each result has required fields
const required = ["review_id", "sentiment", "issue_category", "priority",
                   "confidence", "needs_human_review", "evidence", "llm_mode"];
for (const [i, r] of (batch.results || []).entries()) {
  for (const f of required) {
    if (!(f in r)) issues.push(`results[${i}].${f} missing`);
  }
}

// Check 4: mock mode warning
const mockCount = (batch.results || []).filter(r => r.llm_mode === "mock").length;
if (mockCount > 0) {
  issues.push(`WARNING: ${mockCount} results are mock — not for business decisions`);
}

// Check 5: error count
if (batch.error_count > 0) {
  issues.push(`ERROR: ${batch.error_count} reviews had errors`);
}

// Check 6: is_mock/llm_mode consistency
for (const r of (batch.results || [])) {
  if (r.llm_mode === "mock" && r.is_mock !== true) {
    issues.push(`${r.review_id}: llm_mode=mock but is_mock!=true`);
  }
  if (r.llm_mode === "real" && r.is_mock !== false) {
    issues.push(`${r.review_id}: llm_mode=real but is_mock!=false`);
  }
}

return [{
  json: {
    ...batch,
    _validation: {
      passed: issues.filter(i => !i.startsWith("WARNING")).length === 0,
      issue_count: issues.length,
      issues: issues
    }
  }
}];

// ── Build Feishu Alert Message Card ──────────────────────────────
const batch = $input.first().json;
const urgentItems = (batch.results || []).filter(r =>
  r.needs_human_review === true || r.priority === "high"
);

const alerts = urgentItems.map(r => {
  const evidence = (r.evidence || []).join("; ") || "(无)";
  return [
    `**【${r.review_id}】${r.issue_category} | ${r.priority}**`,
    `摘要: ${r.summary_zh}`,
    `建议: ${r.suggested_action_zh}`,
    `证据: ${evidence}`,
    `置信度: ${(r.confidence * 100).toFixed(0)}% | 模式: ${r.llm_mode}`
  ].join("\n");
});

const card = {
  msg_type: "interactive",
  card: {
    header: {
      title: { content: `⚠️ 评论需关注 — ${urgentItems.length} 条`, tag: "plain_text" },
      template: urgentItems.length > 2 ? "red" : "yellow"
    },
    elements: [
      {
        tag: "div",
        text: { tag: "lark_md", content: alerts.join("\n---\n") }
      },
      {
        tag: "hr"
      },
      {
        tag: "note",
        elements: [{
          tag: "plain_text",
          content: `总计: ${batch.total} | Mock: ${batch.mock_count} | 错误: ${batch.error_count} | ${new Date().toISOString()}`
        }]
      }
    ]
  }
};

return [{ json: card }];

// ── Generate Daily Report ────────────────────────────────────────
const batch = $input.first().json;

const sentimentCounts = { positive: 0, neutral: 0, negative: 0 };
const categoryCounts = {};
const teamCounts = {};

for (const r of (batch.results || [])) {
  sentimentCounts[r.sentiment] = (sentimentCounts[r.sentiment] || 0) + 1;
  categoryCounts[r.issue_category] = (categoryCounts[r.issue_category] || 0) + 1;
  teamCounts[r.responsible_team] = (teamCounts[r.responsible_team] || 0) + 1;
}

const report = [
  '# 📊 Daily Review Analysis Report',
  '',
  `> Generated: ${new Date().toISOString()} | Mode: ${batch.results?.[0]?.llm_mode || '?'}`,
  '',
  '## Summary',
  '',
  `| Metric | Count |`,
  `|--------|-------|`,
  `| Total Reviews | ${batch.total} |`,
  `| Real LLM | ${batch.real_count} |`,
  `| Mock | ${batch.mock_count} |`,
  `| Errors | ${batch.error_count} |`,
  `| Positive | ${sentimentCounts.positive} |`,
  `| Neutral | ${sentimentCounts.neutral} |`,
  `| Negative | ${sentimentCounts.negative} |`,
  `| Needs Human Review | ${batch.needs_human_review_count} |`,
  '',
  '## Category Distribution',
  '',
  ...Object.entries(categoryCounts).map(([k, v]) => `- ${k}: ${v}`),
  '',
  '## Team Distribution',
  '',
  ...Object.entries(teamCounts).map(([k, v]) => `- ${k}: ${v}`)
].join('\n');

return [{ json: { report_markdown: report, batch_summary: batch } }];
